enum LoginError {
    UnknownUser,
    WrongPassword,
    Locked { minutes: u32 },
}

fn login(user: &str, password: &str) -> Result<(), LoginError> {
    if user != "admin" {
        return Err(LoginError::UnknownUser);
    }
    if password == "locked" {
        return Err(LoginError::Locked { minutes: 5 });
    }
    if password != "secret" {
        return Err(LoginError::WrongPassword);
    }
    Ok(())
}

fn main() {
    let attempts = [("admin", "secret"), ("bob", "x"), ("admin", "oops"), ("admin", "locked")];
    for (user, password) in attempts {
        match login(user, password) {
            Ok(()) => println!("{user}: welcome"),
            Err(LoginError::UnknownUser) => println!("{user}: no such user"),
            Err(LoginError::WrongPassword) => println!("{user}: wrong password"),
            Err(LoginError::Locked { minutes }) => {
                println!("{user}: locked, try again in {minutes} minutes")
            }
        }
    }
}

use std::fmt;

enum LoginError {
    UnknownUser,
    WrongPassword,
}

impl fmt::Display for LoginError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            LoginError::UnknownUser => write!(f, "no such user"),
            LoginError::WrongPassword => write!(f, "wrong password"),
        }
    }
}

fn main() {
    let errors = [LoginError::UnknownUser, LoginError::WrongPassword];
    for e in errors {
        println!("Login failed: {e}");
    }
}

use std::num::ParseIntError;

enum ConfigError {
    BadNumber(ParseIntError),
    TooLoud(u32),
}

impl From<ParseIntError> for ConfigError {
    fn from(e: ParseIntError) -> ConfigError {
        ConfigError::BadNumber(e)
    }
}

fn read_volume(s: &str) -> Result<u32, ConfigError> {
    let v: u32 = s.parse()?;   // a ParseIntError becomes a ConfigError
    if v > 100 {
        return Err(ConfigError::TooLoud(v));
    }
    Ok(v)
}

fn main() {
    for input in ["70", "150", "loud"] {
        match read_volume(input) {
            Ok(v) => println!("volume set to {v}"),
            Err(ConfigError::TooLoud(v)) => println!("{v} is over the limit of 100"),
            Err(ConfigError::BadNumber(e)) => println!("{input} is not a number: {e}"),
        }
    }
}

